{"command": "cat > src/main.rs <<'RS'
use std::io::{self, Read};
use std::process;

const VERSION: &str = "tuc 1.3.0\n";
const HELP: &str = include_str!("help.txt");
const SHORT: &str = include_str!("short.txt");

fn main() {
    let args: Vec<String> = std::env::args().collect();
    // args[0] is program name
    let raw: Vec<String> = args[1..].to_vec();
    // Early help/version check (including combined)
    // Check for help first
    if has_flag(&raw, 'h', "help") {
        print_and_exit(HELP, 0);
    }
    if has_flag(&raw, 'V', "version") {
        print_and_exit(VERSION, 0);
    }
    match parse_args(&raw) {
        Ok(cfg) => {
            if let Err(e) = run(cfg) {
                // e is (stdout_partial already printed?, stderr msg, exit code)
                // run handles printing
                std::process::exit(e);
            }
        }
        Err((stdout, stderr, code)) => {
            if !stdout.is_empty() {
                use std::io::Write;
                let _ = io::stdout().write_all(stdout.as_bytes());
            }
            if !stderr.is_empty() {
                use std::io::Write;
                let _ = io::stderr().write_all(stderr.as_bytes());
            }
            process::exit(code);
        }
    }
}

fn print_and_exit(s: &str, code: i32) -> ! {
    use std::io::Write;
    let _ = io::stdout().write_all(s.as_bytes());
    process::exit(code);
}

fn has_flag(raw: &[String], short: char, long: &str) -> bool {
    for arg in raw {
        if arg == &format!("-{}", short) || arg == &format!("--{}", long) {
            return true;
        }
        // combined shorts like -gh, -Vj, -hV etc: only for single-dash, no '='
        if arg.starts_with('-') && !arg.starts_with("--") && !arg.contains('=') {
            let chars: Vec<char> = arg[1..].chars().collect();
            // if all chars are known booleans? For help/version detection, just check if contains
            // We should check if arg looks like combined booleans (all in gpsVzhmj) and contains target
            let bools = ['g','p','s','V','z','h','m','j'];
            if chars.iter().all(|c| bools.contains(c)) && chars.contains(&short) {
                return true;
            }
            // Also handle cases like -Vj where V is combined? Already covered.
            // What about -h with attached? -h is boolean, no attached, so fine.
        }
    }
    false
}

// Config
#[derive(Debug, Clone)]
struct Config {
    greedy: bool,
    compress: bool,
    only_delimited: bool,
    zero_terminated: bool,
    complement: bool,
    join: Option<bool>, // None default, Some(true)=join, Some(false)=no-join
    json: bool,
    no_mmap: bool,
    fields: Option<String>,
    bytes: Option<String>,
    characters: Option<String>,
    lines: Option<String>,
    delimiter: Option<String>,
    regex: Option<String>,
    replace: Option<String>,
    trim: Option<String>,
    fallback_oob: Option<String>,
    fixed_memory: Option<String>,
    file: Option<String>,
}

fn parse_args(raw: &[String]) -> Result<Config, (String, String, i32)> {
    // Returns Ok(cfg) or Err((stdout, stderr, code))
    let mut cfg = Config {
        greedy: false, compress: false, only_delimited: false, zero_terminated: false,
        complement: false, join: None, json: false, no_mmap: false,
        fields: None, bytes: None, characters: None, lines: None,
        delimiter: None, regex: None, replace: None, trim: None,
        fallback_oob: None, fixed_memory: None, file: None,
    };
    // track seen for duplicate detection
    let mut seen_g = false; let mut seen_p = false; let mut seen_s = false;
    let mut seen_z = false; let mut seen_m = false; let mut seen_j = false;
    let mut seen_join = false; let mut seen_nojoin = false; let mut seen_json = false; let mut seen_nommap = false;
