    // track seen for duplicate detection
    let mut seen_g = false; let mut seen_p = false; let mut seen_s = false;
    let mut seen_z = false; let mut seen_m = false; let mut seen_j = false;
    let mut seen_join = false; let mut seen_nojoin = false; let mut seen_json = false; let mut seen_nommap = false;
    let mut seen_f = false; let mut seen_b = false; let mut seen_c = false; let mut seen_l = false;
