                let val = parts[1];
                match opt {
                    "--fields" | "--bytes" | "--characters" | "--lines" | "--delimiter" | "--regex" | "--replace-delimiter" | "--trim" | "--fallback-oob" | "--fixed-memory" => {
                        if val.is_empty() {
                            // e.g., --fields= with empty -> missing value error (as observed)
                            let disp = opt;
                            return Err((String::new(), format!("the '{}' option doesn't have an associated value\n", disp), 1));
                        }
