                            "--fields" => { if seen_f { true } else { seen_f=true; cfg.fields=Some(val.to_string()); false } },
                            "--bytes" => { if seen_b { true } else { seen_b=true; cfg.bytes=Some(val.to_string()); false } },
                            "--characters" => { if seen_c { true } else { seen_c=true; cfg.characters=Some(val.to_string()); false } },
                            "--lines" => { if seen_l { true } else { seen_l=true; cfg.lines=Some(val.to_string()); false } },
                            "--delimiter" => { if seen_d { true } else { seen_d=true; cfg.delimiter=Some(val.to_string()); false } },
                            "--regex" => { if seen_e { true } else { seen_e=true; cfg.regex=Some(val.to_string()); false } },
                            "--replace-delimiter" => { if seen_r { true } else { seen_r=true; cfg.replace=Some(val.to_string()); false } },
                            "--trim" => { if seen_t { true } else { seen_t=true; cfg.trim=Some(val.to_string()); false } },
                            "--fallback-oob" => { if seen_fallback { true } else { seen_fallback=true; cfg.fallback_oob=Some(val.to_string()); false } },
                            "--fixed-memory" => { if seen_M { true } else { seen_M=true; cfg.fixed_memory=Some(val.to_string()); false } },
                            _ => false,
                        };
                        if dup {
                            // report duplicate as [opt, val]? For long with =, original? Need to check: --fields=1 --fields=2 duplicate? Let's assume ["--fields","2"]? But with = form, how reported? Test needed.
                            // For now report as [arg]
                            unexpected.push(arg.clone());
                        }
                    },
                    "--join" | "--no-join" | "--json" | "--no-mmap" | "--greedy-delimiter" | "--compress-delimiter" | "--only-delimited" | "--version" | "--zero-terminated" | "--help" | "--complement" => {
                        // boolean with = is unexpected (as observed --join=true)
                        unexpected.push(arg.clone());
                    },
                    _ => {
                        unexpected.push(arg.clone());
                    }
                }
                i+=1;
                continue;
            } else {
                // no =
                match arg.as_str() {
                    "--fields" | "--bytes" | "--characters" | "--lines" | "--delimiter" | "--regex" | "--replace-delimiter" | "--trim" | "--fixed-memory" => {
                        // need next arg as value
                        if i+1 >= raw.len() {
