                            "--bytes" => { if seen_b { true } else { seen_b=true; cfg.bytes=Some(val.clone()); false } },
                            "--characters" => { if seen_c { true } else { seen_c=true; cfg.characters=Some(val.clone()); false } },
                            "--lines" => { if seen_l { true } else { seen_l=true; cfg.lines=Some(val.clone()); false } },
                            "--delimiter" => { if seen_d { true } else { seen_d=true; cfg.delimiter=Some(val.clone()); false } },
                            "--regex" => { if seen_e { true } else { seen_e=true; cfg.regex=Some(val.clone()); false } },
                            "--replace-delimiter" => { if seen_r { true } else { seen_r=true; cfg.replace=Some(val.clone()); false } },
                            "--trim" => { if seen_t { true } else { seen_t=true; cfg.trim=Some(val.clone()); false } },
                            "--fixed-memory" => { if seen_M { true } else { seen_M=true; cfg.fixed_memory=Some(val.clone()); false } },
                            _ => false,
                        };
                        if dup {
                            unexpected.push(arg.clone());
                            unexpected.push(val.clone());
                        }
                        i+=2;
                        continue;
                    },
                    "--fallback-oob" => {
                        // special: if no next or next is known option, report unexpected for current?
                        // For simplicity, if no next, report unexpected (to match original bare case)
                        if i+1 >= raw.len() {
                            unexpected.push(arg.clone());
                            i+=1;
                            continue;
                        }
                        let val = raw[i+1].clone();
                        // if val is known option (like --join, -f, etc.), then don't consume, report unexpected for current
                        if is_known_option(&val) {
                            unexpected.push(arg.clone());
                            i+=1;
                            continue;
                        }
                        if seen_fallback {
                            unexpected.push(arg.clone());
                            unexpected.push(val.clone());
                        } else {
                            seen_fallback=true;
                            cfg.fallback_oob=Some(val.clone());
                        }
                        i+=2;
                        continue;
                    },
                    "--join" => {
                        if seen_join { unexpected.push(arg.clone()); }
                        else { seen_join=true; 
                            if cfg.join == Some(false) {
                                // will handle later as simultaneous error? Actually -j --no-join gives simultaneous error, not unexpected.
                                // For --join --no-join, original gives simultaneous error, not unexpected.
                                // So we need to allow both to be seen, then error later.
                            }
                            cfg.join = Some(true); seen_j=true;
                        }
                        i+=1; continue;
                    },
                    "--no-join" => {
                        if seen_nojoin { unexpected.push(arg.clone()); }
                        else { seen_nojoin=true; cfg.join = Some(false); }
                        i+=1; continue;
                    },
                    "--json" => {
                        if seen_json { unexpected.push(arg.clone()); } else { seen_json=true; cfg.json=true; }
                        i+=1; continue;
                    },
                    "--no-mmap" => {
                        if seen_nommap { unexpected.push(arg.clone()); } else { seen_nommap=true; cfg.no_mmap=true; }
                        i+=1; continue;
                    },
                    "--greedy-delimiter" => {
                        if seen_g { unexpected.push(arg.clone()); } else { seen_g=true; cfg.greedy=true; }
                        i+=1; continue;
                    },
                    "--compress-delimiter" => {
                        if seen_p { unexpected.push(arg.clone()); } else { seen_p=true; cfg.compress=true; }
                        i+=1; continue;
                    },
                    "--only-delimited" => {
                        if seen_s { unexpected.push(arg.clone()); } else { seen_s=true; cfg.only_delimited=true; }
                        i+=1; continue;
                    },
                    "--complement" => {
                        if seen_m { unexpected.push(arg.clone()); } else { seen_m=true; cfg.complement=true; }
                        i+=1; continue;
                    },
                    "--zero-terminated" => {
                        if seen_z { unexpected.push(arg.clone()); } else { seen_z=true; cfg.zero_terminated=true; }
                        i+=1; continue;
                    },
                    "--help" | "--version" => {
                        // already handled early, but if here, treat as normal? Should have exited.
                        i+=1; continue;
                    },
                    _ => {
                        unexpected.push(arg.clone());
                        i+=1; continue;
                    }
                }
            }
        } else if arg.starts_with('-') && arg.len() > 1 {
            // short option(s)
            // Check for combined booleans like -gs, -gz etc.
            // If arg is exactly "-j" etc., handle.
            // If arg is like "-f1", "-d-", "-M10", "-t...", handle attached.
            // For simplicity:
            // If arg == "-g","-p","-s","-V","-z","-h","-m","-j" single char boolean -> handle
            // Else if arg == "-f","-b","-c","-l","-d","-e","-r","-t","-M" single char option without value -> need next arg
            // Else if arg starts with "-f","-b" etc. with attached (len>2) -> attached value (strip leading '-' + first char, remainder, strip leading '=' if present, if empty -> missing? Actually -f= with empty after = should be missing? We saw -f= gives missing? Actually -f= ? Test: -f= ? We had -f= ? The test with -f= ? We had "-f=" ? Actually we tested "-f=" ? The test with "-f=" ? Let's see: we had "-f=" ? The test showed "-f=" ? Actually we had "-f=" ? Hmm. For "-f=" (i.e., arg "-f="), remainder is "=", strip '=' => "" empty => missing? Original gave missing for "-f=" ? Actually we tested "--fields=" gave missing, but not "-f=". Let's assume same: if remainder after stripping '=' is empty, then missing.
            // Else if arg is like "-gs" (multiple booleans) -> expand if all chars are booleans
            // Else unexpected.

            if arg == "-g" {
                if seen_g { unexpected.push(arg.clone()); } else { seen_g=true; cfg.greedy=true; }
                i+=1; continue;
            } else if arg == "-p" {
                if seen_p { unexpected.push(arg.clone()); } else { seen_p=true; cfg.compress=true; }
                i+=1; continue;
            } else if arg == "-s" {
                if seen_s { unexpected.push(arg.clone()); } else { seen_s=true; cfg.only_delimited=true; }
                i+=1; continue;
            } else if arg == "-z" {
                if seen_z { unexpected.push(arg.clone()); } else { seen_z=true; cfg.zero_terminated=true; }
                i+=1; continue;
            } else if arg == "-m" {
                if seen_m { unexpected.push(arg.clone()); } else { seen_m=true; cfg.complement=true; }
                i+=1; continue;
            } else if arg == "-j" {
                if seen_j { unexpected.push(arg.clone()); } else { seen_j=true; seen_join=true; cfg.join=Some(true); }
