                i+=1; continue;
            } else if arg == "-V" || arg == "-h" {
                // already handled
                i+=1; continue;
            } else if arg == "-f" || arg == "-b" || arg == "-c" || arg == "-l" || arg == "-d" || arg == "-e" || arg == "-r" || arg == "-t" || arg == "-M" {
                // need next arg
                let optchar = arg.chars().nth(1).unwrap();
                if i+1 >= raw.len() {
                    return Err((String::new(), format!("the '{}' option doesn't have an associated value\n", arg), 1));
                }
                let val = raw[i+1].clone();
                // For -t, -d, -e, -r etc., if val is known option that takes value? Original reports missing for some.
                // For simplicity, consume unconditionally (will match most cases)
                // But to better match --trim case, we could check: if optchar == 't' and val is known option, report missing?
                // Let's implement special: for -t, -d, -e, -r, if val is known option that takes value (like -f, -d, etc. or --fields etc.), then report missing for current.
                // For -f, -b, -c, -l, -M, always consume (since any string could be bounds/integer, even if looks like option, original consumes for -f)
