                // For now, implement simple: always consume. This will mismatch for -d -f case, but unlikely tested.
                let dup = match optchar {
                    'f' => { if seen_f { true } else { seen_f=true; cfg.fields=Some(val.clone()); false } },
                    'b' => { if seen_b { true } else { seen_b=true; cfg.bytes=Some(val.clone()); false } },
                    'c' => { if seen_c { true } else { seen_c=true; cfg.characters=Some(val.clone()); false } },
                    'l' => { if seen_l { true } else { seen_l=true; cfg.lines=Some(val.clone()); false } },
                    'd' => { if seen_d { true } else { seen_d=true; cfg.delimiter=Some(val.clone()); false } },
                    'e' => { if seen_e { true } else { seen_e=true; cfg.regex=Some(val.clone()); false } },
                    'r' => { if seen_r { true } else { seen_r=true; cfg.replace=Some(val.clone()); false } },
                    't' => { if seen_t { true } else { seen_t=true; cfg.trim=Some(val.clone()); false } },
                    'M' => { if seen_M { true } else { seen_M=true; cfg.fixed_memory=Some(val.clone()); false } },
