                };
                if dup {
                    unexpected.push(arg.clone());
                    unexpected.push(val.clone());
                }
                i+=2;
                continue;
            } else if arg.starts_with('-') && !arg.starts_with("--") {
                // Could be attached like -f1, -d-, -M10, -t..., or combined like -gs, -gtl, etc.
                // First, check if it's combined booleans (all chars in gpsVzhmj)
                let inner = &arg[1..];
                let bools = ['g','p','s','V','z','h','m','j'];
                if inner.chars().all(|c| bools.contains(&c)) {
