                        // e.g., "-f=" with empty after = -> missing? Original gave missing for "-f=" ? Let's treat as missing.
                        return Err((String::new(), format!("the '-{}' option doesn't have an associated value\n", first), 1));
                    }
                    let dup = match first {
                        'f' => { if seen_f { true } else { seen_f=true; cfg.fields=Some(rest.clone()); false } },
                        'b' => { if seen_b { true } else { seen_b=true; cfg.bytes=Some(rest.clone()); false } },
                        'c' => { if seen_c { true } else { seen_c=true; cfg.characters=Some(rest.clone()); false } },
                        'l' => { if seen_l { true } else { seen_l=true; cfg.lines=Some(rest.clone()); false } },
                        'd' => { if seen_d { true } else { seen_d=true; cfg.delimiter=Some(rest.clone()); false } },
                        'e' => { if seen_e { true } else { seen_e=true; cfg.regex=Some(rest.clone()); false } },
                        'r' => { if seen_r { true } else { seen_r=true; cfg.replace=Some(rest.clone()); false } },
                        't' => { if seen_t { true } else { seen_t=true; cfg.trim=Some(rest.clone()); false } },
                        'M' => { if seen_M { true } else { seen_M=true; cfg.fixed_memory=Some(rest.clone()); false } },
