fn bound_to_range_bytes(b: &Bound, total: usize) -> Result<Option<(usize, usize)>, ()> {
    let s = b.start.unwrap_or(1);
    let e_opt = b.end;
    let total_i = total as i64;
    if total == 0 { return Ok(None); }
    let s_pos: i64 = if s > 0 { s-1 } else { total_i + s };
